package dns
import("fmt";"net";"sort";"strings";"sync")
type AnycastNode struct{ID string `json:"id"`;Address string `json:"address"`;Region string `json:"region"`;Enabled bool `json:"enabled"`;Healthy bool `json:"healthy"`;Priority uint32 `json:"priority"`};type MeshAnycastConfig struct{Enabled bool `json:"enabled"`;Nodes []AnycastNode `json:"nodes"`};type MeshAnycastController struct{mu sync.RWMutex;nodes map[string]AnycastNode;enabled bool}
func NewMeshAnycastController()*MeshAnycastController{return &MeshAnycastController{nodes:make(map[string]AnycastNode)}}
func(c *MeshAnycastController)SetEnabled(enabled bool){if c==nil{return};c.mu.Lock();defer c.mu.Unlock();c.enabled=enabled}
func(c *MeshAnycastController)Upsert(node AnycastNode)error{if c==nil{return fmt.Errorf("controller is nil")};node.ID=strings.TrimSpace(node.ID);node.Address=strings.TrimSpace(node.Address);node.Region=strings.TrimSpace(node.Region);if node.ID==""||node.Address==""{return fmt.Errorf("node ID and address are required")};if host,_,err:=net.SplitHostPort(node.Address);err==nil{if net.ParseIP(host)==nil{return fmt.Errorf("invalid anycast node address")}}else if net.ParseIP(node.Address)==nil{return fmt.Errorf("invalid anycast node address")};c.mu.Lock();defer c.mu.Unlock();if c.nodes==nil{c.nodes=make(map[string]AnycastNode)};c.nodes[node.ID]=node;return nil}
func(c *MeshAnycastController)Config()MeshAnycastConfig{if c==nil{return MeshAnycastConfig{Nodes:[]AnycastNode{}}};c.mu.RLock();defer c.mu.RUnlock();nodes:=make([]AnycastNode,0,len(c.nodes));for _,n:=range c.nodes{nodes=append(nodes,n)};sort.SliceStable(nodes,func(i,j int)bool{if nodes[i].Priority!=nodes[j].Priority{return nodes[i].Priority<nodes[j].Priority};return nodes[i].ID<nodes[j].ID});return MeshAnycastConfig{Enabled:c.enabled,Nodes:nodes}}
func(c *MeshAnycastController)HealthyNodes()[]AnycastNode{if c==nil{return []AnycastNode{}};c.mu.RLock();defer c.mu.RUnlock();out:=make([]AnycastNode,0,len(c.nodes));if !c.enabled{return out};for _,n:=range c.nodes{if n.Enabled&&n.Healthy{out=append(out,n)}};sort.SliceStable(out,func(i,j int)bool{if out[i].Priority!=out[j].Priority{return out[i].Priority<out[j].Priority};return out[i].ID<out[j].ID});return out}
